"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Vítej na meteoritu! Jsi bojový robot Konsorcia. Rozhlédni se myší a jdi pomocí WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Jetpack: klepni na Shift pro skok, drž Shift pro let. Energie se obnovuje na zemi.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Střílej — levé tlačítko. Mířit — pravé tlačítko: přesněji a s přiblížením. Vystřel pár ran.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Nabíjení — R. Kulky nejvíc zaberou na střední vzdálenost, 20–50 metrů.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Raketa — Q. Proti tankům a budovám. Vypusť raketu.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Nahoře je úkol od stratéga. Běž po zelených šipkách: na trase sprintuješ. Dobýt bod — stůj poblíž majáku.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Tvůj oddíl ti kryje záda: vlevo jsou jejich portréty a zdraví. Když zaostávají, požádají tě, ať počkáš.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — rychlé přepnutí jednotky bez opuštění boje: skok do oddílu nebo tanku nejblíž k potyčce. Vyzkoušej to.",
"Next to a tank or turret press E to take control. Or just carry on.":"Vedle tanku nebo věže stiskni E a převezmeš nad nimi kontrolu. Nebo prostě pokračuj dál.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Teď strategie. Klepni na „◩ Strategie“ vpravo nahoře — pohled na bojiště shora.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Teď strategie. Stiskni {0} (nebo „◩ Strategie“ vlevo nahoře) — pohled na bojiště shora.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"Ve strategii ti pomáhá Průvodce: okno nahoře říká, co udělat, rámeček ukazuje tlačítko, kruh označuje místo na mapě. Splň tři jeho rady.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Vyber oddíl a klepni na zelené tlačítko „▶ Ovládnout“ — zpátky do boje za toho vojáka. Zatímco střílíš, AI stratég velí armádě sám.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Vyber oddíl a stiskni {0} nebo zelené „▶ Ovládnout“ — zpátky do boje za toho vojáka (bez výběru — za svého). Zatímco střílíš, AI stratég velí armádě sám.",
