"Rotate your phone to landscape":"Otoč telefon na šířku",
"The heavy MG is a reward the strategist hands out for completed orders.":"Těžký kulomet dává stratég jako odměnu za splněné rozkazy.",
"{0} unlocks at rank \"{1}\". XP comes from kills, captures and strategist orders (×2–×3).":"{0} se odemkne na hodnosti „{1}“. Zkušenosti dávají zabití, dobytí bodů a rozkazy stratéga (×2–×3).",
"Left thumb — move, right thumb — look. Red button — fire.":"Levý palec — pohyb, pravý — rozhled. Červené tlačítko — palba.",
"⇑ — jetpack: tap to hop, hold to fly. ◎ — aim.":"⇑ — jetpack: klepnutím skoč, podržením leť. ◎ — zaměřování.",
"In the air, ⤓ is the jet brake.":"Ve vzduchu ⤓ je brzda jetpacku.",
"Move and shoot: mouse to look, LMB to fire.":"Pohybuj se a střílej: myš — rozhled, levé tlačítko — palba.",
"At the top is the AI strategist's order. Follow it: ×2 and ×3 XP, and completed orders can earn rewards. The green marker and chevrons lead the way.":"Nahoře je rozkaz AI stratéga. Plň ho: zkušenosti ×2 a ×3 a za splnění bývají odměny. Zelená značka a šipky vedou k cíli.",
"Shift — jump pack: tap to hop, hold to fly. RMB — aim.":"Shift — jetpack: klepnutím skoč, podržením leť. Pravé tlačítko — zaměřování.",
"In the air, C is the jet brake. Stop, turn with the mouse and thrust again.":"Ve vzduchu je C brzda jetpacku. Zastav, otoč se pohledem a znovu přidej tah.",
"Enemy vehicle or structure nearby. A rocket is best against them.":"Poblíž je nepřátelská technika nebo stavba. Proti nim je nejlepší raketa.",
"Enemies are bunched up — throw a grenade.":"Nepřátelé se shlukli — hoď granát.",
"Lots of hostiles — trigger Reflex: time slows down and you can pick them off.":"Spousta nepřátel — spusť reflex: čas se zpomalí a stihneš je všechny sundat.",
"Aim at the enemy cluster and call in a strike.":"Zamiř na shluk nepřátel a vyvolej úder.",
"Targets are far — the railgun is stronger at long range.":"Cíle jsou daleko — railgun je silnější na dálku.",
"You have a temporary heavy MG — use it before it is recalled.":"Máš dočasný těžký kulomet — použij ho, než ti ho odeberou.",
"Parkour: C while running — slide, jump at a ledge — climb it, jump next to a wall in the air — wall-jump.":"Parkour: C za běhu — podkluz, skok u římsy — vyšplhat, skok u zdi ve vzduchu — odraz od zdi.",
"Bullets hit hardest at 20–50 m. Point-blank and long range are much weaker — for enemies too.":"Kulky zasahují nejsilněji na 20–50 m. Zblízka i z dálky jsou znatelně slabší — i proti tobě.",
"Your robot is badly damaged. Get out of the fire — armor self-repairs out of combat.":"Robot je těžce poškozen. Uteč z palby — mimo boj se pancíř opravuje sám.",
"One of our tanks is close. Walk up and press E to take control.":"Poblíž je náš tank. Dojdi k němu a stiskni E — budeš ho řídit.",
"Man the turret — press E next to it.":"Obsaď věž — E vedle ní.",
"It is quiet here. Switch to a squad or vehicle closer to the fight.":"Tady je ticho. Přepni se na oddíl nebo techniku blíž k boji.",
"Reload early while no enemies are around.":"Přebíjej si předem, dokud nejsou poblíž nepřátelé.",
"Sprint right along the strategist's green chevrons — you run faster on his route.":"Běž přímo po zelených šipkách stratéga — na jeho trase běžíš rychleji.",
"\"◩ Strategy\" button — top view: build the base, order troops, command squads.":"Tlačítko „◩ Strategie“ — pohled shora: stav základnu, objednávej vojáky, velej oddílům.",
"Strategy mode: build the base, order troops, call strikes and command squads. The same key there possesses the selected unit.":"Režim strategie: stav základnu, objednávej vojáky, vyvolávej údery a velej oddílům. Stejná klávesa tam znamená ovládnout vybraného.",
"Want full command? Turn off the AI strategist — then you give the orders.":"Chceš velet sám? Vypni AI stratéga — pak rozkazy dáváš ty.",
"Third-person view — to see your robot.":"Pohled z třetí osoby — abys viděl svého robota.",
"Tank: {0} — barrage at your aim point, {1} — smoke screen, {2} — overdrive. {3} — back to infantry.":"Tank: {0} — salva do cíle zaměřovače, {1} — kouřová clona, {2} — forsáž. {3} — zpět do pěchoty.",
"Plenty of targets — fire a barrage.":"Cílů je hodně — vypal salvu.",
"Drone: {0}/{1} — up/down, LMB — fire, {2} — ram your aim point.":"Dron: {0}/{1} — výš/níž, levé tlačítko — palba, {2} — ramování do cíle zaměřovače.",
"Select a squad — LMB, drag a box or a card on the left. RMB on the ground — attack-move ⚔, on an enemy — attack, on a point — capture.":"Vyber oddíl — levým tlačítkem, rámečkem nebo kartou vlevo. Pravé tlačítko na zem — útočný pohyb ⚔, na nepřítele — útok, na bod — dobytí.",
"Squads have abilities: grenades, jet leap, suppression, repair. Tanks: barrage, smoke, overdrive.":"Oddíly mají schopnosti: granáty, skok na jetpacích, potlačení, opravu. Tanky: salva, kouř, forsáž.",
"Plenty of ore — select the HQ or a factory and order troops in its panel on the right.":"Rudy je hodně — vyber velitelství nebo továrnu a v panelu vpravo objednej vojáky.",
"Command points are piling up — \"Powers\" tab: recon, artillery, squad drop pod, orbital strike.":"Hromadí se velitelské body (VB) — záložka „Údery“: průzkum, dělostřelecký úder, výsadkový modul s oddílem, orbitální úder.",
"Only builders construct buildings: select a builder (button in the Build tab or a building key), then click the spot. An extractor (C) on a glowing vein — more ore.":"Budovy staví jen stavitelé: vyber stavitele (tlačítko v záložce Stavba nebo klávesa budovy), pak klikni na místo. Extraktor (C) na zářící žílu — víc rudy.",
"Click \"ORE\" at the top left — where ore comes from and how to boost income.":"Klikni na „RUDA“ vlevo nahoře — odkud se ruda bere a jak zrychlit příjem.",
"Ctrl+1…9 — save a group, 1…9 — select it, double-tap — jump the camera.":"Ctrl+1…9 — uložit skupinu, 1…9 — vybrat ji, dvojité stisknutí — kamera k ní.",
"Select a unit and tap the green \"▶ Possess\" below (or double tap) to fight yourself. \"◩ Strategy\" brings you back.":"Vyber jednotku a klepni na zelené „▶ Ovládnout“ dole (nebo dvojitě klepni) — bojuješ sám. „◩ Strategie“ tě vrátí sem.",
"Select a unit and press the green \"▶ Possess\" below or {0} (or double-click) to fight yourself. In battle {1} brings you back.":"Vyber jednotku a stiskni zelené „▶ Ovládnout“ dole nebo {0} (nebo dvojklik) — bojuješ sám. V boji {1} tě vrátí do strategie.",
"Grey buttons can be pressed too: you will see what is missing, how long to wait and how to fix it.":"Šedá tlačítka jde také stisknout: ukážeme ti, co chybí, jak dlouho čekat a jak to napravit.",
"RMB on the ground — rally point for this building's new troops.":"Pravé tlačítko na zem — místo shromáždění pro nové vojáky této budovy.",
"RMB — attack-move ⚔: they stop to fight enemies they meet, then continue. Double RMB — march »: run without stopping, firing on the move. Hold/Retreat — \"More orders ▾\".":"Pravé tlačítko — útočný pohyb ⚔: když narazí na nepřítele, zastaví se a bojují, pak jdou dál. Dvojité pravé tlačítko — pochod »: běh bez zastavení se střelbou za pohybu. Držet/Ústup — „Další rozkazy ▾“.",
"Camera: drag with a finger, two fingers — zoom and rotate, drag on the minimap too.":"Kamera: táhni prstem, dvěma prsty — zoom a otáčení, táhnout lze i minimapu.",
"Camera: WASD and screen edges, Q/E rotate, wheel zoom (to cursor), MMB orbit, minimap — click or drag, Space — to the latest alert.":"Kamera: WASD a okraje obrazovky, Q/E otáčení, kolečko — zoom (ke kurzoru), prostřední tlačítko — rotace, minimapa — klik nebo tažení, mezerník — k poslednímu poplachu.",
