"Only builders build. No builder selected — the button picks the nearest idle one and starts the blueprint; then LMB on a spot.":"Staví jen stavitel. Není vybrán stavitel — tlačítko vybere nejbližšího volného a zapne plán; pak levé tlačítko na místo.",
