"On — builds the base, orders troops and gives orders by itself (your orders take priority). Off — you do everything.":"Zapnuto — samo staví základnu, objednává vojáky a rozdává rozkazy (tvé rozkazy mají přednost). Vypnuto — vše děláš ty.",
