"Then click (tap) the ground: they move and fight on the way. On an enemy — attack it. Same as RMB.":"Pak klikni (klepni) na zem: pohybují se a cestou bojují. Na nepřítele — zaútočit. Stejné jako pravé tlačítko.",
"Run":"Běh",
"Then click (tap) the ground: they run without engaging. Same as double RMB.":"Pak klikni (klepni) na zem: běží bez boje. Stejné jako dvojité pravé tlačítko.",
