"New in v6.3":"Novinky ve v6.3",
"New in v6.2":"Novinky ve v6.2",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Nový vzhled rudy: žíly jsou zářící smaragdové broušené krystaly na černém čediči s jiskrami a zeleným oparem; extraktor je šestiboký podstavec s plástvovou kupolí a mřížovou věží se zeleným majákem (pruh a vlajka v barvě týmu)",
"New in v6.1":"Novinky ve v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Preferovaná třída jako v Battlefieldu (U, čísla po smrti): při obnovení se objevíš v ní, pokud je k dispozici",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"jemné automatické míření — zapnout v Nastavení",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Z Jádra se snadno dostaneš: mezerník — k šachtě, B — kapsle na povrch; efekty schopností se po smrti resetují",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Nekonečný postup: generálové a Maršál ★, kariérní úrovně, mistrovství zbraní a doplňky, medaile, denní zakázky — obrazovka Kariéra",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Strategie: plynulý zoom kolečkem, ikony a popisky jednotek (Alt — všechny), panel Vojsko / Budovy vlevo",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"pravé tlačítko — přesun s bojem po cestě, dvojité pravé tlačítko — pochod se střelbou za pohybu; vzácné rozkazy v „Další rozkazy ▾\"; tlačítka se neopakují",
"New in v6":"Novinky ve v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Střelba jako ve střílečkách: okamžité kulky, puška 720 ran/min, kulomet, zpětný ráz, mířidla na pravé tlačítko, zásobníky a přebíjení R, značky zásahů",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Těžší gravitace, citlivější jetpack, úhyb na Z nebo dvojitý jetpack ve vzduchu; při přeskoku do jiného vojáka už zbraň nelétá s tebou",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Inženýři: vyber inženýra, vyber budovu, polož plán; Extraktory na rudných žílách; klik na „RUDA\" ukáže příjem a jak ho zvýšit",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Šedá tlačítka jdou stisknout — ukážeme důvod a tlačítko s řešením; větší tlačítka, pruh „Probíhá\", „▶ Ovládnout\", Tab je jediná klávesa režimů",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Strategická kamera bez trhání a převracení, zoom ke kurzoru, minimapu lze tahat",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Nová technika: nájezdník „Šakal\", raketomet „Grad\" (samonaváděcí rakety), minomet „Kladivo\"; Roj dostává „Vosu\", „Úl\", „Trebuchet\"",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Stratég nemění rozkazy a nespamuje hlasem; boje probíhají u tebe; B — přesun, Shift+B — do víru boje; kompas, H — který cíl",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Volná hra (K) a hra na vlastní pěst (J), F2 — předvolby; Esc — pauza a zpět; ukládání: sloty, export a import souboru",
"New in v5.3":"Novinky ve v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Let: silnější gravitace daleko od meteoritu, C ve vzduchu brzdí, tah řídí ostřeji; už neuvázneš v portálu",
"New in v5":"Novinky ve v5",
"Endless war by default and battle scale: normal, large, epic":"Výchozí nekonečná válka a velikost bitev: běžná, velká, epická",
"Save and load the battle (autosave every 3 minutes)":"Ukládání a načítání bitvy (a automatické ukládání každé 3 minuty)",
"Squadmates with callsigns: portraits, health and live chatter":"Družstvo s volacími znaky: portréty, zdraví a živé hovory",
"Fog of war in strategy, friends and foes outlined differently":"Mlha války ve strategii, přátelé a nepřátelé jinak zvýrazněni",
"Camera fly-over when switching, portal aurora instead of rings":"Přelet kamery při přepnutí, záře portálu místo kruhů",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Vedlejší úkoly, zkratka přes nebe, moduly první expedice se zásobami, krystaly, led v kráterech, prachové bouře",
"Training, cinema mode with video recording, escort vehicles from the strategist":"Výcvik, filmový režim s nahráváním videí, doprovodná technika od stratéga",
