"Grenade: hold G to see the arc and blast circle; drag on the button to aim; release to throw.":"Granát: drž G — uvidíš oblouk a kruh výbuchu; táhni prstem po tlačítku — úhel; pusť — hod.",
"Grenade: hold {0} for the arc and blast circle, release to throw. Range — by view angle, wheel — power, RMB — underhand.":"Granát: drž {0} pro oblouk a kruh výbuchu, pusť pro hod. Dosah — úhlem pohledu, kolečko — síla, pravé tlačítko — pod sebe.",
"Grenades: hold G for the flight arc, blast point and radius, distance; release to throw. Range by view angle, wheel — power, RMB — underhand":"Granáty: drž G — oblouk letu, bod a kruh výbuchu, vzdálenost; pusť — hod. Dosah úhlem pohledu, kolečko — síla, pravé tlačítko — pod sebe",
"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"Granát se odráží a koulí po svahu, výbuch za 2,5 s; 2 granáty, obnova 9 s; ikona varování před nepřátelským granátem poblíž",
"Grenade: hold — arc and blast point, release — throw · tank overdrive":"Granát: drž — oblouk a bod výbuchu, pusť — hod · přetížení tanku",
