"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"Granát ({0}): drž — oblouk letu, bod a kruh výbuchu, vzdálenost; pusť — hod; krátký stisk hodí hned. Dosah úhlem pohledu, kolečko — síla, pravé tlačítko — pod sebe. Telefon: drž G a táhni prstem.",
