"The Polygon works in developer mode only":"Cvičiště funguje jen v režimu vývojáře",
"⚔ Polygon: an endless battle at the map centre with reinforcements. X — possess a soldier there":"⚔ Cvičiště: nekonečný boj ve středu mapy s posilami. X — ovládnout tam vojáka",
