"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Klepni na „Zaměřit“ — přiblížení. Další klepnutí — zpět.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Oddíl jde za tebou. Otevři ☰ → „Pauza“ → dlaždice „Oddíl se mnou“ — změní se na „Jednám sám“.",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Inženýr je vybrán — klepni na „◆ Těžit krystaly“ v jeho kartě dole (nebo klepni na zelené krystaly).",
"Training complete!":"Výcvik dokončen!",
"steps":"kroků",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Umíš stavět základnu, objednávat vojsko, velet a skákat do boje. Dál už je skutečný zápas: Průvodce ti poradí za pochodu.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Umíš se pohybovat, létat, střílet, krýt se a velet oddílu. Dál už je skutečný zápas.",
"Real battle":"Skutečný boj",
"Again":"Znovu",
"done":"splněno",
"you are on PC: keyboard and mouse":"máš PC: klávesnice a myš",
"you are on a phone: touch screen":"máš telefon: dotyková obrazovka",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Bezpečné pískoviště: nepřátelé jsou stále jen figuríny, nikdo na tebe nestřílí. Krok se počítá, jen když akci opravdu provedeš.",
"Show others (training for the other device)":"Zobrazit další (výcvik pro jiné zařízení)",
"Old training (v7.1)":"Starý výcvik (v7.1)",
"Back to the normal device mode":"Zpět na běžný režim zařízení",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"Výcvik pro jiné zařízení restartuje stránku v jeho režimu (PC — myš a klávesnice, telefon — dotyk; na PC lze dotyk pohodlně testovat v Chrome: F12 → ikona telefonu).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Výcvik ×4: samostatné krokové lekce „Strategie\" a „Střelec\" pro PC i telefon. Bezpečné cvičiště s figurínami, zvýrazněné správné tlačítko, šipky, animované klávesy, myš a gesta; krok se počítá jen za skutečnou akci, „opakovat krok\", postup nahoře a odměna na konci",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"Nabídka Výcvik sama ukáže lekce pro tvé zařízení; „Zobrazit další\" — všechny čtyři na jakémkoli zařízení; „Starý výcvik (v7.1)\" zůstal",
"New in v7.2":"Novinky ve v7.2",
"NEW IN v7.2":"NOVINKY VE v7.2",
"No grenades left":"Granáty došly",
"Rocket and grenade recharging · {0} s":"Raketa a granát se nabíjejí · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Vlevo — pohyb, vpravo — pohled · klepnutí na nepřítele — raketa / granát · 2 klepnutí — reflex · 3 klepnutí — dělostřelecký úder",
"Less":"Méně",
"More":"Více",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Poblíž je nepřátelská technika nebo stavba — klepni na ni: odpálí se raketa.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Mnoho nepřátel — rychle dvakrát klepni na volné místo vpravo: reflex zpomalí čas.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Zaměř shluk nepřátel a klepni 3krát — dělostřelecký úder.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Levý palec — pohyb, pravý — pohled. Zaměřený nepřítel — střílí se samo.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"⇑ vlevo u okraje — jetpack: klepnutím skočíš, přidržením poletíš.",
"Old v7.2 layout":"Starý layout v7.2",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Veď prstem po pravé polovině obrazovky — pod prstem se objeví joystick pohledu.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Dotkni se vlevo a veď prst — pod prstem se objeví joystick. Dojdi k zelené značce.",
"Hold the \"Jet\" button at the left edge.":"Drž tlačítko „Jetpack\" u levého okraje.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Pravým joystickem zamiř na figurínu — voják střílí sám, když je zaměřovač na cíli.",
"Tap the dummy on the screen — a rocket flies.":"Klepni na figurínu na obrazovce — vyletí raketa.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Klepni na figurínu — poletí granát (do cíle, obloukem).",
"Double tap an empty spot on the right quickly.":"Rychle dvakrát klepni na volné místo vpravo.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Lehký režim pro slabé telefony: nižší rozlišení, bez stínů a zkreslení, poloviční počet botů a částic, max. 30 FPS; sám sníží rozlišení, když FPS < 25. Na telefonu je ve výchozím stavu zapnutý (Nastavení → Grafika → „Lehký režim\"; nebo ?lite=1 / ?lite=0 v odkazu).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Telefon: nové ovládání. Vlevo — pohyb, vpravo — pohled (oba joysticky se objeví pod prstem). Jen levý palec — „auto\"; když se použije i pravý, voják střílí sám, jen když je zaměřovač na nepříteli. Klepnutí na nepřítele — raketa nebo granát, 2 klepnutí — reflex, 3 klepnutí — dělostřelecký úder. Automatické přebíjení. Jetpack — tlačítko u levého okraje. Spodní rohy jsou volné, minimapa v rohu, nápovědy jdou zavřít křížkem, úkol lze sbalit. Starý layout: Nastavení → Telefon.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Nápovědy (vyskakovací i Průvodce) — jeden přepínač v nastavení. Za koho hraješ (typ vojáka nebo techniky) — popisek „Ty: …\" v HUD. Optiky pušky a kulometu jsou průhledné. Panel „Arzenál\" je ukotvený vpravo, jde sbalit i vypnout. Režim „sám bez oddílu\" (J) je pryč. Hlas stratéga už neopakuje stále tutéž větu. Tanky mají indikátor věže vůči trupu. Kurzor už nemizí na začátku výcviku strategie.",
