"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Telefon: tři režimy joysticků. Jen levý — „auto\" (silný magnet, slabší kulky). Jen pravý — zaměřovač se zapne sám, silnější magnet, přesnější střelba. Oba — bez zaměřování, slabší magnet i přesnost. Tlačítko 👁 vpravo skryje/vrátí rozhraní.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Telefon: strategie zjednodušena — jen inženýr a budovy. Vlevo karty (inženýr, velitelství, kasárna…): klepnutí — kamera tam přeletí, dole je hned vidět, co stavět/vyrábět. „Do boje\" — vlevo nahoře. Armáda bojuje sama. Plná strategie — Nastavení → Telefon.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Ovládnutí — dva přepínače: „Oddíly\" a „Technika\" (na telefonu je technika ve výchozím stavu vypnutá — řídí ji AI). Při vypnuté technice E (na telefonu tlačítko vpravo) vedle vlastního stroje — sednout ke kanónu: stroj jede sám, ty střílíš. Staré „vlastní pořadí tříd\" je v „Pokročilých\". Při ovládnutí jednotka odpoví do vysílačky.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Chytré nápovědy: základní samy zhasnou po 2. spuštění, ale hra tě upozorní na funkci, kterou stále nepoužíváš. Přepínače: základní / pokročilé / vzácné, zvlášť hlas nápověd a Průvodce.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Reflex se nabíjí ze zabití (série nabíjí víc). Parťáci zaostali nebo padli — stratég k tobě vysadí nové (dráž než běžné posily). Grafika a zvuk v7.2gfx jsou začleněny: mohutné výbuchy, kouř, trosky, akustika šachet a kráterů. Datum sestavení je už skutečné.",
