"both bases built and upgraded — for footage":"obě základny postaveny a vylepšeny — pro natáčení",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Kino režim — rozdělená obrazovka: vlevo bot-stratég (pohled shora na základnu a armádu), vpravo bot-střelec z první osoby. Tlačítka dole (a klávesy S, P): „Rozdělená obrazovka\" a „★ Vše postaveno\" — obě základny postavené a vylepšené pro natáčení.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Jádro a tunely skrz meteorit jsou pryč — meteorit je plný, boj probíhá jen na povrchu.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Telefon: 👁 skryje HUD, ale nechá jetpack, ⇆, páčky a značku cíle. „◎ Zaměřit\" (jen pravým prstem) — výrazně silnější a širší magnet; síla magnetu pro všechny tři režimy — Nastavení → Ovládání → „Pokročilé\". U kanónu vozidla se tlačítko jmenuje „Slézt\".",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Výcvik: na telefonu jen telefonní lekce, na PC jen PC. Všechny 4 jsou v nabídce „🛠 Vývojář\". Režim vývojáře a Arzenál jsou teď jedna nabídka (v boji — „🛠 Menu\" vpravo nahoře, na PC F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Grafické styly „Dendy (8bit)\" a „16bit\": Nastavení → Grafika → „Styl grafiky\" (podrobnosti — tlačítko ⚙). Pokud je FPS v prvních ~10 s zápasu pod 24, Dendy se zapne samo (pod 20 — větší pixely, 120 řádků); oznámení „vrátit normální\" obnoví normální grafiku napořád. Tvoje vlastní volba v nabídce má vždy přednost.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D modely prostředí (ruiny, vraky, opevnění) — jen ty s dobrým hodnocením, načítají se na požádání. Vypnout: Nastavení → Grafika → „Nové 3D modely prostředí\".",
