"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Stavba vojáky: E (na telefonu „Vstoupit\") u vlastní stavby — voják staví sám, spolubojovníci poblíž pomáhají. Pokud jsou inženýři zaneprázdněni, stratég tě sám požádá o pomoc — značka „STAVBA\".",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Značky stratéga: stratég umístí ⌖ na skupinu nepřátel poblíž tebe — o 8 s později tam udeří dělostřelectvo a blízké spojenecké MLRS „Grad\" vypustí salvu. Tvůj vlastní dělostřelecký úder ze strategického režimu má podporu „Gradů\" také.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Skrýše se zbraněmi v nákladních kontejnerech a spadlých satelitech (📦 vidět z 70 m): E — těžký kulomet na 90 s, zápalná munice nebo rakety, plus plné granáty. Plazení: Ctrl — lehnout / vstát (níž, stabilněji, přesněji, ale pomalu).",
