"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"„▶ Hrát hned\" — první tlačítko nabídky: krátký přelet pod nebem-portálem a rovnou do boje (přeskočit lze libovolnou klávesou nebo klepnutím).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Zásahy je cítit: kovový zvuk a jiskry, značka zabití u zaměřovače (headshot — žlutá), série ×N, plynulé třesení od výbuchů, zpomalení při důležitých zabitích. Třesení, zpomalení i nápovědu lze vypnout v Nastavení.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Výsledek zápasu: čas, zničení, nejlepší série, ★ MVP a nejlepší oddíl, karta zápasu — „⇪ Sdílet\", PNG nebo odkaz na hru.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Nápověda „co dělat teď\" vlevo pod zdroji: rozkaz stratéga, bod k dobytí, útok Roje. ✕ nebo F7 — sbalit.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Boj se uloží sám, když zavřeš nebo skryješ kartu — v nabídce „⟲ Pokračovat\".",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"Verze v7.5 zůstává v nabídce „🕘 Verze hry\" — kdyby se ti nová nelíbila. Nově se odesílají anonymní statistiky (bez jmen a e-mailů); vypnout lze v Nastavení.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"„Hrát hned\", odezva zásahů, výsledek zápasu s kartou, nápověda „co dělat\", automatické ukládání",
"and older: v7.5, v7.4, milestones v1–v7.0":"a starší: v7.5, v7.4, milníky v1–v7.0",
"New in v7.6":"Novinky ve v7.6",
"NEW IN v7.6":"NOVINKY VE v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Výběr frakce před zápasem: „Konsorcium\" (těžká pěchota v silovém brnění, pancéřování a dělostřelectvo) nebo „Roj\" (rychlost, smečky dronů, těžké výstřely se zkreslením). Za druhou hraje AI. Volba se pamatuje.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Každá frakce má vlastní techniku a unikáty: Konsorcium — tank „Nosorožec\" a „Keramitové pláty\", Roj — „Smečka dronů\" a „Fázové jetpacky\". Vyváženost ověřena zápasy botů.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Krátery po výbuších: dělostřelectvo, rakety a tankové kanóny ryjí v meteoritu jámy — můžeš jimi chodit a jezdit a v jejich nitru se kdykoli ukrýt.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Pohled z 3. osoby pro vojáka (V, pamatuje se; na telefonu — Ovládání) a plynulá kamera techniky se značkou, kam kanón dopadne.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"Verze v7.6 zůstala v nabídce „🕘 Verze hry“ pro případ, že ti nová nebude sedět.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Frakce Konsorcium / Roj s výběrem před zápasem, krátery po výbuších, pohled z 3. osoby",
"and older: v7.6, v7.5, milestones v1–v7.0":"a starší: v7.6, v7.5, milníky v1–v7.0",
