"dormant":"spí",
"Anomaly ahead! The vein is singing — go around!":"Anomálie před námi! Žíla zpívá — obejděte ji!",
"Hear that hum? A singing vein. Keep clear!":"Slyšíte ten hukot? Zpívající žíla. Nepřibližovat se!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Anomálie! Vzduch se točí — to je vír, obejdi ho!",
"Rocks floating in the air… A whirlpool! Stay out!":"Kameny visí ve vzduchu… Vír! Nelez tam!",
"Anomaly ahead — it is crackling with current!":"Anomálie před námi — praská to proudem!",
"Rods and lightning — a Crackler. It loves armour!":"Hroty a blesky — Praskač. Brnění miluje!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Anomálie! Země se chvěje žárem — Žhavý koš!",
"Careful, a Brazier underfoot!":"Opatrně, pod nohama Žhavý koš!",
"Anomaly — green mist! Acid, hold your breath!":"Anomálie — zelená mlha! Kyselina, nedýchat!",
"The mist is drifting our way, go around!":"Mlha se plazí k nám, obcházíme!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Anomálie! Vzduch jako sklo — Čočka, ohýbá kulky!",
"Everything is warping… a Lens nearby!":"Obraz se kroutí… Čočka poblíž!",
"Ha! An enemy walked right into the anomaly!":"Ha! Nepřítel vešel přímo do anomálie!",
"Got him! Lure them into anomalies!":"Mám ho! Nalákej je do anomálií!",
"Beautiful zap! One less tin can.":"Krásná rána! O plechovku míň.",
"The anomaly got me!":"Anomálie mě zasáhla!",
"Ow! Don't go in there!":"Au! Nelezte tam!",
"Discharged! It is dormant now.":"Vybito! Teď spí.",
"Clear, the anomaly is discharged.":"Čisto, anomálie vybita.",
"They say veins hide artifacts. Only first the vein sings…":"Prý se ve žilách ukrývají artefakty. Jenže nejdřív žíla zpívá…",
"Throw a bolt first, then walk. Old habit.":"Nejdřív hoď šroub, pak jdi. Stará pověra.",
"throw a bolt":"hodit šroub",
"📦 Supply drop: landing in 4 seconds":"📦 Zásobovací bedna: shoz za 4 sekundy",
