"at the crosshair · ✕ — close":"podle zaměřovače · ✕ — zavřít",
"target — crosshair · ":"cíl — zaměřovač · ",
" — close":" — zavřít",
"Supply drop":"Zásobovací bedna",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Shodí bednu poblíž tvých sil: náboje, granáty, rakety, díly zbraní, opravná sada.",
"\"Grad\" rocket strike":"Úder „Gradu“",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"16 raket na velkou plochu za 3 sekundy — rychlejší a širší než dělostřelecký úder.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Podpora: bedna, průzkum, „Grad“, dělostřelecký úder (pak 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"POZOR: „Grad“ Roje míří na vaši oblast!",
"Warning! Rocket salvo on our position!":"Pozor! Raketová salva na naši pozici!",
"take the supply crate":"vzít zásobovací bednu",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Anomálie na meteoritu (vlna 1): „Zpívající žíla“ — svítící zelený krystal, který hučí a rytmickými pulzy zasahuje všechny poblíž; „Vír“ táhne a mrští, „Praskač“ sršící blesky mezi hroty, „Žhavý koš“ vzplane pod nohama, „Kyselá mlha“ a „Čočka“ (ohýbá kulky i obraz) se potulují okolím.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Anomálie je cítit předem (hukot, záře, chvění vzduchu). Vybít ji můžeš granátem, raketou nebo šroubem (E u anomálie): usne a občas zanechá artefakt s plusem i mínusem. Oddíl varuje přes vysílačku a nepřátelé (i vlastní) do nich občas vlezou — nalákej je!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Podpora za body velení: 4 v boji (na telefonu 📡) — zásobovací bedna, průzkum, úder „Gradu“, dělostřelecký úder podle zaměřovače. Stratég vidí anomálie na mapě až po průzkumu.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Zásobovací bedny v troskách starých expedic, u velitelství a vedle dostavěných budov: náboje, granáty, rakety, díly zbraní (odemykají příslušenství).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"Verze v7.7 zůstala v nabídce „🕘 Verze hry“. Anomálie lze vypnout v Nastavení.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomálie („Zpívající žíla“ a 5 dalších), vybíjení šroubem a granátem, artefakty, podpora za velitelské body, zásobovací bedny",
"and older: v7.7, v7.6, milestones v1–v7.0":"a starší: v7.7, v7.6, milníky v1–v7.0",
"New in v7.8":"Novinky ve v7.8",
"NEW IN v7.8":"NOVINKY VE v7.8",
"Close":"Zavřít",
"Anomalies on the meteor":"Anomálie na meteoritu",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ v rohu otevře nabídku pauzy: Pokračovat, Začít znovu, Výcvik, Grafika, Nastavení, Hlavní nabídka (s potvrzením). Telefon: ☰ vpravo nahoře (akce boje — dlaždice „⚡ Akce“); PC: tlačítko „☰ Nabídka“ vpravo nahoře nebo Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Grafika je ve výchozím stavu vždy normální — Dendy jen podle tvé volby: přepínač „Grafika: Normální / Dendy (8bit) / 16bit“ je přímo v hlavní nabídce i v pauze. Když hra hodně sekává, objeví se tip s tlačítkem „Zapnout Dendy“.",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Telefon a tablet: tlačítko akce „✋“ vpravo se objeví, jen když je poblíž co dělat — „Vzít“ (skrýš, bedna), „Nasednout“ (technika, věž, kanón), „Stavět“, „Slézt“, „Šroub“ u anomálie. Můžeš také jen klepnout na zvýrazněný předmět.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Telefon, strategie: podrž prst ~0,3 s (telefon zavibruje, objeví se žlutý kroužek) a táhni — výběrový rámeček; běžné švihnutí posouvá kameru. Vpravo je také tlačítko „Rámeček“; ve výcviku krok „Rámeček“ uzná i výběr oddílu klepnutím.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Telefon: drobná tlačítka se snáz trefují, seznam podpory 📡 je větší, panely strategie už nezasahují do pauzy a výsledků. Verze v7.8 zůstala v nabídce „🕘 Verze hry“.",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"Nabídka ☰ na telefonu i PC, žádné automatické Dendy, tlačítko „✋“ na telefonu, výběr rámečkem na telefonu",
"16-bit":"16bit",
"Lagging? Try the Dendy graphics — they are lighter.":"Sekává to? Zkus grafiku Dendy — je méně náročná.",
"Turn on Dendy":"Zapnout Dendy",
"Use":"Akce",
