"Pause: resume, restart, training, graphics, settings, main menu":"Pauza: pokračovat, znovu, výcvik, grafika, nastavení, hlavní nabídka",
"Menu: pause, restart, training, graphics, settings":"Nabídka: pauza, znovu, výcvik, grafika, nastavení",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Podrž prst na zemi ~0,3 s — telefon zavibruje a objeví se žlutý kroužek — a bez zvednutí táhni: vznikne rámeček. Nebo použij tlačítko „Rámeček“ vpravo. Stačí také klepnout na oddíl.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Pro celou obrazovku na iPhonu: „Sdílet“ ⬆ → „Přidat na plochu“ — hra se otevře bez panelů Safari.",
"Open portal-meteor.pages.dev for that.":"Otevři k tomu stránku portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Klepnutí — vybrat · klepnutí na zem — jít · podržení — nabídka rozkazů · podržení a tažení — rámeček · 2 prsty — zoom",
"Robo-ninja":"Robo-ninja",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Hrdinka-zabijačka: výpady-teleporty, katana, shurikeny. Sama skáče po zónách nepřítele a rozsekává roboty. 1 na stranu.",
"Shadow protocol":"Protokol „Stín“",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Výzkum: odemkne robo-ninju v Kasárnách. Vyžaduje dokončenou továrnu na mechy.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Hrdinka (1 na stranu): sama se teleportuje po zónách nepřítele a rozsekává roboty; můžeš ji Ovládnout a hrát ručně.",
"is ready. She works on her own (AUTO) — possess her to play manually":"je připravena. Pracuje sama (AUTO) — Ovládni ji, abys hrála ručně",
"Robo-ninja ready for action":"Robo-ninja je připravena k boji",
"⚠ Intel: the enemy has a robo-ninja!":"⚠ Průzkum: nepřítel má robo-ninju!",
"Warning! The enemy has a robo-ninja. Stay together":"Pozor! Nepřítel má robo-ninju. Držte spolu",
