"order":"rozkaz",
"nearby":"poblíž",
"Zone cleared":"Zóna vyčištěna",
"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ SOUBOJ NINJŮ! Blok těsně před zásahem odrazí úder, výpad je úhyb. Sleduj záblesk přípravy",
"The two ninjas have met in a duel!":"Dvě ninji se střetly v souboji!",
"⚔ Duel won! Our ninja prevails":"⚔ Souboj vyhrán! Naše ninja je silnější",
"⚔ Duel lost…":"⚔ Souboj prohrán…",
"ninja duel":"souboj ninjů",
