"Teleport: aim at the ground (up to 150 m)":"Teleport: zamiř na zem (do 150 m)",
"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ AUTO: sama skáče po zónách nepřítele a seká. Joystick / WASD — pauza 1,5 s",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Ručně: klepnutí na nepřítele — výpad a úder, švihnutí — seknutí, 🛡 — blok",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"Ruční ovládání: levé tlačítko — katana, pravé tlačítko — blok, Shift — blink, Q — shurikeny, G — teleport",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ninja: klepnutí na nepřítele — výpad a seknutí, švihnutí vpravo — sek, ● — úder, 🛡 — blok (včas = parírování), ⇑ — blink, ✦ — shurikeny, ◎ — teleport, AUTO — sama",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ninja: levé tlačítko — katana (držet — těžký sek), pravé tlačítko — blok (včas = parírování), Shift/Z — blink, Q — shurikeny, G — teleport k zaměřovači, skok ve vzduchu — dvojskok / běh po zdi, {0} — AUTO",
