"Research complete: Shadow protocol — the robo-ninja is available in the Barracks":"Výzkum dokončen: Protokol Stín — v Kasárnách je dostupná robo-ninja",
"Shadow protocol ready. The robo-ninja can be deployed":"Protokol Stín je připraven. Můžeš povolat robo-ninju",
"✶ Our robo-ninja is down. Deploy her again in the Barracks":"✶ Naše robo-ninja byla zničena. Můžeš ji znovu povolat v Kasárnách",
