"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Rádio Portal Meteor: 100+ skladeb od EDMITRY přímo ve hře — tlačítko 📻 (PC: klávesa 5, [ ] — skladba). Hudba se streamuje na požádání a hru nezatěžuje; hlasitost a automatický start v Nastavení, plus odkaz „Poslouchat na Spotify“.",
