"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 vpravo — Rádio Portal Meteor: hudba od EDMITRY během boje.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Rádio Portal Meteor: hudba od EDMITRY během boje. [ ] — skladba.",
"Radio Portal Meteor (EDMITRY): volume":"Rádio Portal Meteor (EDMITRY): hlasitost",
"Radio: start by itself in battle":"Rádio: samo se zapne v boji",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-ninja: kyborg s katanou. Odemyká se v Kasárnách výzkumem „Protokol Stín“ (potřebuje továrnu na mechy). Sama se teleportuje do zón nepřítele, rozsekává nepřátele (bez krve — jiskry), výpady, shurikeny, souboje s nepřátelskou ninjou. Ovládni ji — režim AUTO nebo ruční řízení (na telefonu vlastní tlačítka).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Rádio Portal Meteor: 103 skladeb EDMITRY přímo ve hře. Klávesa 5 (lze přemapovat), na telefonu — ☰ → Nastavení → Zvuk. Hlasitost a „zapnout samo v boji“ jsou v nastavení; hudba se při explozích a hlasu vysílačky ztlumí.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Nové jazyky: uzbečtina a tádžičtina — kompletně; čínština, španělština, portugalština — částečně. Nový výběr jazyka v menu vedle „Nový zápas“.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Telefon: „skrýt ikony“ 👁 seskupí zbylá tlačítka do úhledného sloupce u pravého okraje; na výšku už se nepřekrývají; iPhone — hra už nekoliduje s gesty Safari a „Sdílet → Přidat na plochu“ ji spustí na celou obrazovku.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Z v7.8.1: menu ☰ v rohu (pauza, restart, výcvik, grafika), žádné automatické Dendy, akční tlačítko ✋ na telefonu. v7.8.1 a v7.8 zůstaly v menu „🕘 Verze hry“.",
"Robo-ninja, EDMITRY radio, Uzbek and Tajik, phone and iPhone UX":"Robo-ninja, rádio EDMITRY, uzbečtina a tádžičtina, pohodlí na telefonu a iPhonu",
