"A bomber drops 10 bombs along an 80 m strip, approaching from your base (in battle — along your view). After 3.5 s, leaves craters.":"Bombardér shodí 10 bomb v pruhu 80 m ve směru náletu od tvé základny (v boji — ve směru pohledu). Po 3,5 s zanechá krátery.",
