"A 12 m fire zone burns for 9 seconds: damage over time, suppression, smoke. After 2.5 s. Ignites methane.":"Ohnivá zóna 12 m hoří 9 sekund: poškození v čase, potlačení, kouř. Po 2,5 s. Zapálí metan.",
