"Consortium. Boss: 15000 hull, cannon, 2 MGs, rockets. Very slow. Weak spot — the rear. One per army.":"Konsorcium. Boss: 15000 trupu, kanón, 2 kulomety, rakety. Velmi pomalý. Slabé místo — záď. Jeden na armádu.",
