"Living world: requests, hero quests, breakthrough ops":"Živý svět: prosby svých, úkoly hrdinů, přelom v boji",
"Living world":"Živý svět",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Tví vojáci prosí o pomoc a odměňují tě, hrdinové zadávají úkoly, zdlouhavou frontu prolomí operace",
"A request":"Prosba svých",
"Breakthrough":"Přelom v boji",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Tví vojáci občas prosí o pomoc: hlas v rádiu, karta „PROSBA“ a značka ✋. Oddíl je přišpendlený — znič nepřátele poblíž. Odměna: voják výsadkovým modulem ze základny, zbraň z korby buginy, místo střelce nebo krytí z orbity. Nechceš — ✕ nebo prostě ignoruj.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Veterán-průzkumník „Sova“ nabízí úkol. Y — přijmout (N — odmítnout). Jdi ke značce ★, vyřaď stráže a postůj u pilota 3 s — přidá se do tvého oddílu.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Fronta stojí — velitelství nabízí přelom. Y — přijmout. Drž retranslátor 8 s bez nepřátel poblíž: nepřátelská mapa bude vidět 60 s. Generátor — nepřátelské věže mlčí 2 min. Ve Stratégovi — „Zadat oddílu“. Nepřítel to umí taky: sleduj ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Tví vojáci prosí o pomoc: karta „PROSBA“ a značka ✋. Znič nepřátele u přišpendleného oddílu — dostaneš odměnu. ✕ — přeskočit.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Hrdina „Sova“ nabízí úkol — klepni na „Přijmout“. Jdi k ★, vyřaď stráže, postůj u pilota.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Fronta stojí — klepni na „Přijmout“ a drž retranslátor 8 s: nepřátelská mapa se na minutu odhalí.",
"Pod redeploy from the base: {0} m — through the sky portal":"Přesun výsadkovým modulem ze základny: {0} m — přes nebeský portál",
"Pod away from the base! Hold on — exit over the target.":"Modul odstartoval ze základny! Držte se — výstup nad cílem.",
"Landed at the objective!":"Přistání u cíle!",
"LAUNCH FROM BASE":"START ZE ZÁKLADNY",
"LANDING":"PŘISTÁNÍ",
"REDEPLOY":"PŘESUN",
"Steel fluff stuck to you — corrodes armour −2/s. Stand still 3 s out of combat or find an engineer":"Ocelové chmýří se k tobě přilepilo — žere pancíř −2/s. Postůj 3 s mimo boj nebo najdi inženýra",
"An engineer brushed the fluff off":"Inženýr smetl chmýří",
"The fluff fell off — armour is safe":"Chmýří opadalo — pancíř je v pořádku",
"The firefly swarm scattered by the blast":"Roj světlušek rozehnán výbuchem",
"STEEL FLUFF −2/s · stand still 3 s or find an engineer":"OCELOVÉ CHMÝŘÍ −2/s · stůj 3 s mimo boj nebo najdi inženýra",
"Lefty's convoy is ready: two Jackals. Stay close — they wait for you":"Konvoj Leváka je připraven: dva „Šakalové“. Drž se poblíž — čekají na tebe",
"The convoy is waiting for you":"Konvoj na tebe čeká",
"Ambush! Cover the Jackals!":"Přepadení! Kryj „Šakaly“!",
"the convoy made it ({0} of 2)! +2 CP, +150 ore, the Jackals are yours":"konvoj dorazil ({0} z 2)! +2 BV, +150 rudy, „Šakalové“ jsou tvoji",
