"Builds structures and extractors, repairs, cleans Steel fluff off others.":"Staví budovy a extraktory, opravuje, sundává Ocelové chmýří z ostatních.",
"A squad flies from the base launch pad through the sky portal right to the target.":"Oddíl přiletí z odpalovací rampy základny přes nebeský portál přímo k cíli.",
"Squad: ":"Oddíl: ",
