"Members: ":"Složení: ",
"Main battle tank: cannon and MG. Consortium \"Bulldog\" is tougher, Swarm \"Spider\" is faster.":"Hlavní bojový tank: kanón a kulomet. Konsorcium má „Buldoka“ (odolnější), Roj „Pavouka“ (rychlejší).",
"Heavy tank":"Těžký tank",
"Autonomous flying gunner: fast, fragile, fears anti-air.":"Autonomní létající střelec: rychlý, křehký, bojí se protiletadlovek.",
"Upgrade":"Vylepšení",
"Longer, faster jetpacks for all infantry.":"Jetpacky s větším dosahem a rychlostí pro celou pěchotu.",
"Extractors mine more ore.":"Extraktory těží víc rudy.",
"Army-wide levels: less damage taken / more damage dealt.":"Úrovně pro celou armádu: menší poškození vlastních / větší poškození nepřítele.",
"Levels":"Úrovní",
"Base":"Základna",
"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"Srdce základny: oddíly, inženýři, výsadkové moduly, výzkum. Ztráta velitelství znamená porážku.",
"Produces: ":"Vyrábí: ",
"Launch pad":"Odpalovací rampa",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Silo vedle velitelství: odsud startují výsadkové moduly, zásobovací bedny a bombardéry — přes nebeský portál k cíli. Nedá se na ní stavět.",
"Economy":"Ekonomika",
"Key building":"Klíčová budova",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Slabé místo — záď (motor): poškození ×{0}. Kanón, 2 kulometné věže, raketový blok; velmi pomalu se otáčí — obejdi ho z boku.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Slabé místo — zářící jádro pod břichem: poškození zespodu ×{0}. Paprsek zkreslení a plošný dupot; přešlapuje zábrany — držte odstup, netlačte se na hromadu.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Proti němu: letecké bomby a dělostřelectvo (×{0}), rakety (×{1}), kobercové bombardování; kulky ho sotva poškrábou (×{2}).",
"Faction":"Frakce",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Rychlé stroje, roje dronů, tunely a regenerace. Pěchota lehčí, ale rychlejší; kanóny a railguny zasahují silněji.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Těžká pěchota v silových pancířích, betonové zábrany, opravy a dělostřelectvo. Pomalejší, ale odolnější.",
